#!/usr/bin/env python3
"""Assemble the GitHub Pages site for the CockroachDB .NET Library.

Produces, under ``_site/``:

* ``index.html`` — CU-themed landing (matches the developer-libraries site) with
                   a NuGet install snippet and one card per package.
* ``apidocs/``   — generated by DocFX *before* this script runs.
* ``nuget/``     — a minimal **static NuGet v3 feed** (service index +
                   flat-container) that ``dotnet``/NuGet can restore from with no
                   token:  nuget/index.json  +  nuget/flatcontainer/{id}/...

Reads every ``*.nupkg`` under ``./nupkgs`` (produced by ``dotnet pack -o nupkgs``);
id and version come from each package's embedded ``.nuspec`` so they're exact.
"""

from __future__ import annotations

import html
import json
import re
import shutil
import sys
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SITE = ROOT / "_site"
NUPKGS = ROOT / "nupkgs"
REPO_SLUG = "cockroachlabs/cockroachdb-dotnet-library"
PAGES_URL = "https://cockroachlabs.github.io/cockroachdb-dotnet-library"

BLURBS = {
    "CockroachDB.DotNet.Abstractions": "Core interfaces and contracts shared across the stack.",
    "CockroachDB.DotNet.Core": "Middleware pipeline, retry engine, circuit breaker, region context.",
    "CockroachDB.DotNet.Continuum": "Plenum storage insights, vCluster tagging, Aegis, Cloud, MCP.",
    "CockroachDB.DotNet.AI": "pgvector similarity search and RAG pipelines.",
    "CockroachDB.DotNet.Cdc": "Changefeed (CDC) webhook handlers.",
    "CockroachDB.DotNet.EntityFramework": "EF Core provider integration for CockroachDB.",
    "CockroachDB.DotNet.Testing": "xUnit + Testcontainers helpers for CockroachDB.",
}


def read_nuspec(nupkg: Path) -> tuple[str, str]:
    """Return (id, version) from a .nupkg's embedded .nuspec.

    Parsed with a regex rather than an XML parser: the input is a self-produced
    package and this avoids the stdlib XML XXE/billion-laughs surface entirely.
    """
    with zipfile.ZipFile(nupkg) as z:
        name = next(n for n in z.namelist() if n.endswith(".nuspec"))
        text = z.read(name).decode("utf-8", "replace")
    pid = re.search(r"<id>\s*([^<]+?)\s*</id>", text)
    ver = re.search(r"<version>\s*([^<]+?)\s*</version>", text)
    if not pid or not ver:
        raise ValueError(f"{nupkg.name}: could not read id/version from nuspec")
    return pid.group(1), ver.group(1)


def discover() -> list[dict]:
    pkgs = []
    for nupkg in sorted(NUPKGS.glob("*.nupkg")):
        pid, ver = read_nuspec(nupkg)
        pkgs.append({"id": pid, "version": ver, "file": nupkg})
    return pkgs


def build_feed(pkgs: list[dict]) -> None:
    """Minimal static NuGet v3 feed: service index + PackageBaseAddress (flat container)."""
    flat = SITE / "nuget" / "flatcontainer"
    flat.mkdir(parents=True, exist_ok=True)
    # Service index advertising only the flat-container resource (enough to restore).
    (SITE / "nuget" / "index.json").write_text(
        json.dumps(
            {
                "version": "3.0.0",
                "resources": [
                    {
                        "@id": f"{PAGES_URL}/nuget/flatcontainer/",
                        "@type": "PackageBaseAddress/3.0.0",
                    }
                ],
            },
            indent=2,
        )
        + "\n"
    )
    # Group by lowercased id (a package may have >1 version over time).
    by_id: dict[str, list[dict]] = {}
    for pkg in pkgs:
        by_id.setdefault(pkg["id"].lower(), []).append(pkg)
    for idl, versions in by_id.items():
        base = flat / idl
        base.mkdir(parents=True, exist_ok=True)
        vers = sorted(v["version"] for v in versions)
        (base / "index.json").write_text(json.dumps({"versions": vers}, indent=2) + "\n")
        for pkg in versions:
            vdir = base / pkg["version"]
            vdir.mkdir(parents=True, exist_ok=True)
            shutil.copy2(pkg["file"], vdir / f"{idl}.{pkg['version']}.nupkg")


def build_landing(pkgs: list[dict]) -> None:
    version = next((p["version"] for p in pkgs if p["id"] == "CockroachDB.DotNet.Core"), pkgs[0]["version"])
    cards = []
    for pkg in sorted(pkgs, key=lambda p: p["id"]):
        blurb = BLURBS.get(pkg["id"], "CockroachDB .NET package.")
        cards.append(f"""        <div class="card"><a class="card-link" href="./apidocs/">{html.escape(pkg["id"])} API reference</a>
          <span class="mod">{html.escape(pkg["id"])}</span>
          <h3>{html.escape(pkg["id"])}</h3>
          <p>{html.escape(blurb)}</p>
          <div class="go">API reference →</div></div>""")
    cards_html = "\n".join(cards)
    nuget_config = (
        "&lt;!-- NuGet.config --&gt;\n"
        "&lt;configuration&gt;\n"
        "  &lt;packageSources&gt;\n"
        f'    &lt;add key="cockroachlabs" value="{PAGES_URL}/nuget/index.json" /&gt;\n'
        "  &lt;/packageSources&gt;\n"
        "&lt;/configuration&gt;\n\n"
        f"dotnet add package CockroachDB.DotNet.Core --version {html.escape(version)}"
    )
    SITE.mkdir(parents=True, exist_ok=True)
    (SITE / "index.html").write_text(f"""<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>CockroachDB .NET Library — API Reference</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;700&display=swap" rel="stylesheet">
<style>
  :root{{--purple:#9059FF;--purple-dark:#6b32d6;--purple-tint:#efe8ff;--cream:#F2F1EE;--paper:#fff;--ink:#101913;--mute:#5c655d;--faint:#9aa39b;--line:#e4e2dd;--max:1080px;--cu-mono:'Geist Mono',ui-monospace,monospace}}
  *{{box-sizing:border-box}}
  body{{margin:0;font-family:'Geist',system-ui,sans-serif;background:var(--cream);color:var(--ink);-webkit-font-smoothing:antialiased}}
  a{{color:inherit}}
  .nav{{max-width:var(--max);margin:0 auto;padding:20px 26px;display:flex;align-items:center;gap:16px}}
  .brand{{display:flex;align-items:center;gap:10px;font-weight:700;letter-spacing:-.01em;text-decoration:none}}
  .brand .d{{width:12px;height:12px;border-radius:3px;background:var(--purple)}}
  .nav .tag{{font-family:var(--cu-mono);font-size:10.5px;letter-spacing:.8px;text-transform:uppercase;color:var(--purple-dark);border:1px solid #d9c9ff;background:var(--purple-tint);padding:5px 10px;border-radius:99px}}
  .nav .gh{{margin-left:auto;display:inline-flex;align-items:center;color:var(--mute);transition:.15s}}
  .nav .gh:hover{{color:var(--purple)}}.nav .gh svg{{display:block}}
  .hero{{max-width:var(--max);margin:0 auto;padding:46px 26px 10px}}
  .hero .eyebrow{{font-family:var(--cu-mono);font-size:11.5px;letter-spacing:1.6px;text-transform:uppercase;color:var(--purple-dark);display:inline-flex;align-items:center;background:var(--purple-tint);border:1px solid #d9c9ff;padding:6px 14px;border-radius:99px}}
  .hero h1{{font-size:clamp(34px,6vw,58px);font-weight:800;letter-spacing:-.035em;line-height:1;margin:22px 0 0;color:var(--ink)}}
  .hero p{{color:#2b332c;font-size:clamp(15px,2vw,18px);max-width:60ch;margin-top:18px;line-height:1.6}}
  .install{{max-width:var(--max);margin:22px auto 0;padding:0 26px}}
  .install .lbl{{font-family:var(--cu-mono);font-size:10.5px;letter-spacing:.8px;text-transform:uppercase;color:var(--mute);margin:0 0 8px}}
  .install pre{{background:var(--ink);color:#f5f3ef;font-family:var(--cu-mono);font-size:12.5px;line-height:1.5;padding:16px 18px;border-radius:12px;overflow:auto;margin:0}}
  .grid{{max-width:var(--max);margin:30px auto 0;padding:0 26px;display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:18px}}
  .card{{position:relative;display:flex;flex-direction:column;border:1px solid var(--line);border-radius:16px;background:var(--paper);padding:24px;transition:.18s}}
  .card:hover{{transform:translateY(-3px);border-color:var(--purple);box-shadow:0 18px 40px -24px rgba(80,36,130,.3)}}
  .card-link{{position:absolute;inset:0;border-radius:16px;z-index:1;font-size:0;color:transparent}}
  .card>:not(.card-link){{position:relative;z-index:2;pointer-events:none}}
  .card .mod{{align-self:flex-start;font-family:var(--cu-mono);font-size:11px;font-weight:600;letter-spacing:.6px;color:var(--purple-dark);border:1px solid var(--line);background:var(--cream);padding:5px 11px;border-radius:99px;margin-bottom:14px}}
  .card h3{{font-size:18px;font-weight:700;letter-spacing:-.02em;margin:0 0 6px}}
  .card p{{color:var(--mute);font-size:14px;line-height:1.5;flex:1;margin:0}}
  .card .go{{margin-top:16px;font-family:var(--cu-mono);font-size:11px;letter-spacing:.6px;text-transform:uppercase;color:var(--purple)}}
  footer{{max-width:var(--max);margin:60px auto 0;padding:26px;border-top:1px solid var(--line);font-family:var(--cu-mono);font-size:12px;color:var(--faint)}}
</style></head><body>
<header class="nav">
  <a class="brand" href="index.html"><span class="d"></span>CockroachDB .NET Library</a>
  <span class="tag">API Reference</span>
  <a class="gh" href="https://github.com/{REPO_SLUG}" target="_blank" rel="noopener" aria-label="Repository on GitHub" title="View on GitHub"><svg viewBox="0 0 16 16" width="20" height="20" fill="currentColor" aria-hidden="true"><path fill-rule="evenodd" d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82a7.6 7.6 0 012-.27c.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.01 8.01 0 0016 8c0-4.42-3.58-8-8-8z"/></svg></a>
</header>
<section class="hero">
  <span class="eyebrow">NuGet · v{html.escape(version)}</span>
  <h1>API Reference</h1>
  <p>Generated API documentation for the CockroachDB .NET Library — a composable middleware pipeline for retry, circuit breaking, CDC, multi-region, and AI/vector workloads. Install from the GitHub Pages NuGet feed below.</p>
</section>
<section class="install">
  <p class="lbl">Install · NuGet (no token required)</p>
  <pre>{nuget_config}</pre>
</section>
<section class="grid">
{cards_html}
</section>
<footer>Generated from source · Apache-2.0 · The Cockroach Authors</footer>
</body></html>
""")


def main() -> int:
    pkgs = discover()
    if not pkgs:
        print("no .nupkg files found under ./nupkgs", file=sys.stderr)
        return 1
    build_feed(pkgs)
    build_landing(pkgs)
    print(f"built _site: {len(pkgs)} packages, static NuGet feed + landing")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
